files.hooks/register.tsx:
// impact-radius: holds a risky shell command (recursive deletes, git reset --hard, git clean, force
// pushes, discarded changes, migrations and third-party installs for the whole user or system),
// shows what it would change and waits for the person to press Run or Cancel.
//
// It measures with $.fs and git, never bash, so it works the same on Windows. To hold the command,
// the hook waits inside a short `$.process.run` (time spent inside a `$` call doesn't count against
// the hook's budget, except `$.clock.sleep`): `sleep` on Linux and macOS; on Windows, Git for
// Windows' `sleep.exe` or, without it, PowerShell's `Start-Sleep`.

import type { EngineInterface, RenderElement, RenderInput, Register } from 'claude-code'

import { classify, type Risk } from './classify'
import { type Facts, measure, type Probe } from './measure'
import { denyReason, type Lang, langOf, type Reason, type Report, report, words } from './messages'
import { resolvePath, type Shell } from './shell'
import { temporaryPath, temporaryRoots, type TemporaryVariables } from './temp'

const PANE = 'impact-radius'
const WAIT_MAX_MS = 10 * 60 * 1000

type Decision = 'run' | Reason
type Held = {
  command: string
  risks: Risk[]
  report: Report | null
  decision: Decision | null
  place: 'pane' | 'band'
}

let lang: Lang = 'en'
// The held command, or null. One at a time: a turn's commands come one after another, and a
// subagent's waits for the answer to the one before.
let held: Held | null = null
let sleepArgv: Promise<string[]> | null = null
let windows: Promise<boolean> | null = null

// ---------------------------------------------------------------------------
// Environment

function isWindows($: EngineInterface): Promise<boolean> {
  windows ??= (async () => (await $.env.get('OS')) === 'Windows_NT')()
  return windows
}

async function homeOf($: EngineInterface): Promise<string> {
  return ((await $.env.get('USERPROFILE')) || (await $.env.get('HOME')) || '').replace(/\\/g, '/')
}

/** How to wait a moment without spending the hook's budget. */
async function findSleep($: EngineInterface): Promise<string[]> {
  if (!(await isWindows($))) return ['sleep', '0.25']
  try {
    const run = await $.process.run(['git', '--exec-path'], { timeoutMs: 5_000 })
    const path = run.stdout.trim().replace(/\\/g, '/')
    const root = path.replace(/\/(mingw64|mingw32|clangarm64)\/libexec\/git-core\/?$/i, '')
    const sleep = `${root}/usr/bin/sleep.exe`
    if (run.exitCode === 0 && root !== path && (await $.fs.exists(sleep))) return [sleep, '0.25']
  } catch {
    // no Git for Windows: PowerShell is always there
  }
  return ['powershell', '-NoProfile', '-NonInteractive', '-Command', 'Start-Sleep -Milliseconds 300']
}

async function pause($: EngineInterface): Promise<void> {
  sleepArgv ??= findSleep($)
  await $.process.run(await sleepArgv, { timeoutMs: 5_000 })
}

/** Whether the session runs inside a Python virtual environment (not conda's `base`). */
async function inVirtualEnv($: EngineInterface): Promise<boolean> {
  if (await $.env.get('VIRTUAL_ENV')) return true
  return Boolean(await $.env.get('CONDA_PREFIX')) && (await $.env.get('CONDA_DEFAULT_ENV')) !== 'base'
}

/** The real folder of a `cd`, or null when it doesn't exist. */
async function realDir($: EngineInterface, base: string, dir: string): Promise<string | null> {
  if (dir === '-') return null // `cd -` depends on the shell's history
  const path = resolvePath(base, dir, await homeOf($))
  try {
    return (await $.fs.stat(path)).kind === 'dir' ? path : null
  } catch {
    return null
  }
}

/**
 * Whether a delete only touches the system's temporary folder, where Claude keeps its scratch files:
 * every target lies below TEMP, TMP, TMPDIR, /tmp or /var/tmp, exists, and holds no symbolic link or
 * junction, and the walk counted everything. Anything unknown or failing keeps the delete held.
 */
async function temporaryDelete($: EngineInterface, risk: Risk, base: string, shell: Shell): Promise<boolean> {
  if (risk.kind !== 'delete' || risk.targets.length === 0) return false
  try {
    const windows = await isWindows($)
    const vars: TemporaryVariables = { TEMP: await $.env.get('TEMP'), TMP: await $.env.get('TMP'), TMPDIR: await $.env.get('TMPDIR') }
    const roots = temporaryRoots(vars, windows)
    if (roots.length === 0) return false
    const cwd = risk.dir ? await realDir($, base, risk.dir) : base
    if (cwd === null) return false
    const home = await homeOf($)
    const paths = risk.targets.map(target => temporaryPath(target, cwd, home, vars, roots, shell, windows))
    if (paths.some(path => path === null)) return false
    const facts = await measure({ ...risk, targets: paths as string[] }, cwd, await probe($))
    return facts.kind === 'delete' && !facts.truncated && facts.links === 0 && facts.found >= risk.targets.length
  } catch {
    return false
  }
}

/** The engine calls measure.ts needs, so `$` never leaves this file. */
async function probe($: EngineInterface): Promise<Probe> {
  return {
    windows: await isWindows($),
    home: await homeOf($),
    now: () => $.clock.now(),
    stat: path => $.fs.stat(path).then(
      s => s,
      () => null,
    ),
    list: path => $.fs.list(path).then(
      l => [...l],
      () => null,
    ),
    run: (argv, options) =>
      $.process.run(argv, options).then(
        r => ({ exitCode: r.exitCode, stdout: r.stdout, stderr: r.stderr }),
        () => ({ exitCode: -1, stdout: '', stderr: '' }),
      ),
  }
}

const commandOf = (input: unknown) => String((input as { command?: unknown } | undefined)?.command ?? '')
const shellOf = (tool: string): Shell => (tool === 'Bash' ? 'bash' : 'powershell')

/** The effect Claude reads: the first risk's, and the other risky commands of the line. */
function effectOf(entry: Held): string {
  const others = [...new Set(entry.risks.slice(1).map(r => r.command))]
  const summary = entry.report?.summary ?? entry.risks[0]?.command ?? ''
  return others.length > 0 ? `${summary} (${words(lang).also(others.join(', '))})` : summary
}

// ---------------------------------------------------------------------------
// Drawing

/** What another mod draws under the band; the engine's marker (`type: 'engine'`) doesn't count. */
const drawnBelow = (tree: unknown): RenderElement | null =>
  typeof tree === 'object' && tree !== null && (tree as { type?: unknown }).type !== 'engine' ? (tree as RenderElement) : null

// All text is in the theme's text color, the only one that keeps 7:1 contrast in every theme;
// color goes to the border and the icons.
function draw($: EngineInterface, e: RenderInput, entry: Held, below: RenderElement | null = null) {
  const { Box, Text, Button } = $.ui.resolve(e)
  const t = words(lang)
  const first = entry.risks[0]?.command ?? ''
  const r = entry.report ?? { summary: first, lines: [], more: 0, note: '' }
  const others = [...new Set(entry.risks.slice(1).map(x => x.command))]
  const width = Math.max(t.command.length, t.effect.length) + 2
  // The buttons answer for the command they were drawn for, never for whichever is held now.
  const decide = (d: Decision) => () => {
    if (entry.decision === null) entry.decision = d
  }
  // The terminal shows a hotkey only on a plain button; the desktop draws native ones.
  const terminal = e.surface === 'terminal'
  const panel = (
    <Box flexDirection="column" borderStyle="round" borderColor="warning" paddingX={1}>
      <Text bold>
        <Text color="warning">{'⚠ '}</Text>
        {`${t.name}: ${first}`}
      </Text>
      <Box flexDirection="column" marginTop={1}>
        <Text wrap="truncate-end">
          <Text bold>{t.command.padEnd(width)}</Text>
          {entry.command}
        </Text>
        <Text>
          <Text bold>{t.effect.padEnd(width)}</Text>
          <Text color="error">{'● '}</Text>
          <Text bold>{r.summary}</Text>
        </Text>
      </Box>
      {r.lines.length > 0 ? (
        <Box flexDirection="column" marginTop={1}>
          {r.lines.map((line, i) => (
            <Text key={`line-${i}`} wrap="truncate-end">
              {`  ${line}`}
            </Text>
          ))}
          {r.more > 0 && <Text>{`  ${t.more(r.more)}`}</Text>}
        </Box>
      ) : null}
      {r.note ? (
        <Box marginTop={1}>
          <Text wrap="wrap">{r.note}</Text>
        </Box>
      ) : null}
      {others.length > 0 ? <Text wrap="wrap">{t.also(others.join(', '))}</Text> : null}
      <Box flexDirection="row" marginTop={1} gap={2}>
        {terminal ? (
          <Button key="cancel" plain label={t.cancel} hotkey={t.cancelKey} autoFocus onPress={decide('cancel')} />
        ) : (
          <Button key="cancel" variant="primary" label={t.cancel} hotkey={t.cancelKey} autoFocus onPress={decide('cancel')} />
        )}
        {terminal ? (
          <Button key="run" plain label={t.run} hotkey={t.runKey} onPress={decide('run')} />
        ) : (
          <Button key="run" label={t.run} hotkey={t.runKey} onPress={decide('run')} />
        )}
        <Text>{t.waiting}</Text>
      </Box>
    </Box>
  )
  return below ? (
    <Box flexDirection="column">
      {panel}
      {below}
    </Box>
  ) : (
    panel
  )
}

// ---------------------------------------------------------------------------
// Hooks

export const register: Register = (on, options) => {
  lang = langOf(options?.language)

  // Held at the permission check (`tool.check`), not at the run: the person's answer is the
  // permission, so the engine doesn't ask again after Run.
  on('tool.check', async ($, e, next) => {
    if (e.tool !== 'Bash' && e.tool !== 'PowerShell') return next(e)
    // Another plugin's `$.tool.check` is not a command about to run.
    if (!e.tool_use_id) return next(e)
    const command = commandOf(e.input)
    let risks = classify(command, shellOf(e.tool))
    // pip without `--user` inside a virtual environment installs into the project.
    const venvDependent = (r: Risk) => r.kind === 'install' && r.venvDependent === true
    if (risks.some(venvDependent) && (await inVirtualEnv($))) risks = risks.filter(r => !venvDependent(r))
    // A delete inside the temporary folder isn't held: the command goes on to the engine's own check.
    if (risks.some(r => r.kind === 'delete')) {
      const base = (await $.session.cwd()).replace(/\\/g, '/')
      const kept: Risk[] = []
      for (const r of risks) if (!(await temporaryDelete($, r, base, shellOf(e.tool)))) kept.push(r)
      risks = kept
    }
    const first = risks[0]
    if (first === undefined) return next(e)
    // When the person's rules already forbid it, there is nothing to ask.
    const verdict = await next(e)
    if (verdict.decision === 'deny') return verdict
    // Nobody can press anything (a plain `claude -p`): don't wait ten minutes for it.
    if ((await $.session.surfaces()).length === 0) return { decision: 'deny', reason: denyReason('nobody', first.command, lang) }

    // One held command at a time: another one (a subagent's, say) waits for its answer.
    // `held` is checked and taken with no await in between.
    while (held !== null) {
      if (next.signal.aborted) return { decision: 'deny', reason: denyReason('interrupted', first.command, lang) }
      await pause($)
    }
    const mine: Held = { command, risks, report: null, decision: null, place: 'pane' }
    held = mine

    let placed = false
    try {
      const base = (await $.session.cwd()).replace(/\\/g, '/')
      const cwd = first.dir ? await realDir($, base, first.dir) : base
      const facts: Facts = cwd === null ? { kind: 'unmeasured', reason: 'missing-dir', detail: first.dir ?? '' } : await measure(first, cwd, await probe($))
      mine.report = report(first, facts, lang)

      const opened = await $.ui.open({ id: PANE, title: words(lang).name, focus: true })
      placed = opened.isPlaced
      if (!placed) mine.place = 'band'
      $.ui.invalidate('ui.render')

      const start = await $.clock.now()
      while (mine.decision === null) {
        if (next.signal.aborted) {
          mine.decision = 'interrupted'
          break
        }
        if ((await $.clock.now()) - start > WAIT_MAX_MS) {
          mine.decision = 'timeout'
          break
        }
        await pause($)
      }
    } catch {
      mine.decision = 'error' // anything unexpected leaves the command unrun
    } finally {
      // Close this command's pane before letting go, so the next one's isn't closed.
      try {
        if (placed) await $.ui.close({ id: PANE })
      } catch {
        // already closed
      }
      if (held === mine) held = null
      $.ui.invalidate('ui.render')
    }

    const t = words(lang)
    if (mine.decision === 'run') {
      $.ui.toast(`${t.name}: ${t.ran}`)
      return { decision: 'allow', reason: `${t.name}: ${t.allowed}` }
    }
    return { decision: 'deny', reason: denyReason(mine.decision ?? 'error', effectOf(mine), lang) }
  }).catch(($, e, next) => {
    if (e.tool !== 'Bash' && e.tool !== 'PowerShell') return next(e)
    // Not run: the call came in beneath one this hook is holding. Only a risky one is stopped; a
    // delete in the temporary folder is stopped too, since nothing can be measured from here.
    if (next.error.kind === 're-entry') {
      const risks = e.tool_use_id ? classify(commandOf(e.input), shellOf(e.tool)) : []
      const first = risks[0]
      return first === undefined ? next(e) : { decision: 'deny', reason: denyReason('busy', first.command, lang) }
    }
    // A guard that fails doesn't let the command through.
    return { decision: 'deny', reason: denyReason('error', words(lang).notMeasured, lang) }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, ($, e, next) => {
    if (held === null || held.report === null) return next(e)
    return draw($, e, held)
  })

  // When the screen can't place the pane (a narrow terminal), the notice goes above the prompt.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const entry = held
    if (entry === null || entry.report === null || entry.place !== 'band' || e.props.hasSurvey) return next(e)
    return draw($, e, entry, drawnBelow(await next(e)))
  })
}

files.hooks/classify.ts:
// Which shell commands are risky and which folder they run in. Returns data, never prose: the
// words live in messages.ts. No `$`: tested directly.
//
// The idea comes from blast-radius, in Anthropic's claude-code-playground; this code is new and
// also understands PowerShell, Claude's usual shell on Windows, and third-party installs.

import { activatesVenv, type InstallRisk, installRisk } from './installs'
import { commandName, isParam, joinDir, segments, type Shell, stripPrefixes } from './shell'

export type GitOp = 'reset-hard' | 'clean' | 'push-force' | 'discard'
export type MigrationTool = 'django' | 'alembic' | 'rails' | 'prisma' | 'other'

/** `command` is a short literal label (`rm -rf`, `git reset --hard`); `dir` is null for the session's folder. */
export type DeleteRisk = { kind: 'delete'; command: string; dir: string | null; targets: string[] }
export type GitRisk = { kind: 'git'; op: GitOp; command: string; dir: string | null; args: string[] }
export type MigrationRisk = { kind: 'migrate'; tool: MigrationTool; command: string; dir: string | null }
export type Risk = DeleteRisk | GitRisk | MigrationRisk | InstallRisk

/** A change of folder (`cd`, `Set-Location`, `pushd`, `popd`): null is the session's, `-` the unknown previous one. */
type DirChange = { cd: string | null }

/** Commands that only read: a stray "migrate" among their words is not a migration. */
const READ_ONLY = new Set([
  'ls', 'cat', 'echo', 'printf', 'grep', 'rg', 'find', 'less', 'head', 'tail', 'cd', 'git',
  'get-content', 'gc', 'type', 'select-string', 'sls', 'get-childitem', 'gci', 'dir', 'write-output', 'write-host',
])
/** Remove-Item and its PowerShell aliases. */
const POWERSHELL_DELETE = new Set(['remove-item', 'ri', 'rm', 'del', 'erase', 'rd', 'rmdir'])
const POWERSHELL_CD = new Set(['cd', 'chdir', 'sl', 'set-location'])
const PUSHD = new Set(['pushd', 'push-location'])
const POPD = new Set(['popd', 'pop-location'])

function powershellDelete(command: string, args: string[], dir: string | null): DeleteRisk | null {
  const targets: string[] = []
  const flags: string[] = []
  let recurse = false
  let force = false
  for (let i = 0; i < args.length; i++) {
    const a = args[i] ?? ''
    if (!a.startsWith('-')) {
      targets.push(...a.split(',').filter(Boolean))
      continue
    }
    const value = a.includes(':') ? a.slice(a.indexOf(':') + 1) : undefined
    if (isParam(a, 'whatif', 1)) return null // only shows what it would do
    if (isParam(a, 'recurse', 1)) {
      recurse = true
      flags.push('-Recurse')
    } else if (isParam(a, 'force', 2)) {
      force = true
      flags.push('-Force')
    } else if (isParam(a, 'path', 1) || isParam(a, 'literalpath', 1) || /^-(lp|pspath)$/i.test(a.split(':')[0] ?? '')) {
      const v = value ?? args[++i]
      if (v) targets.push(...v.split(',').filter(Boolean))
    } else if (['filter', 'include', 'exclude', 'credential', 'stream'].some(n => isParam(a, n, 2)) && value === undefined) {
      i++ // its value is not a path
    }
  }
  if (!recurse && !force) return null
  return { kind: 'delete', command: `${command} ${flags.join(' ')}`.trim(), dir, targets }
}

function bashDelete(args: string[], dir: string | null): DeleteRisk | null {
  const end = args.indexOf('--')
  const options = (end < 0 ? args : args.slice(0, end)).filter(a => a.startsWith('-') && a !== '-')
  const recurse = options.some(f => f === '--recursive' || (/^-[^-]/.test(f) && /[rR]/.test(f)))
  const force = options.some(f => f === '--force' || (/^-[^-]/.test(f) && f.includes('f')))
  if (!recurse && !force) return null
  const targets = end < 0 ? args.filter(a => !a.startsWith('-') || a === '-') : [...args.slice(0, end).filter(a => !a.startsWith('-')), ...args.slice(end + 1)]
  return { kind: 'delete', command: `rm ${options.join(' ')}`.trim(), dir, targets }
}

function gitRisk(args: string[], dir: string | null): GitRisk | null {
  let gitDir = dir
  let i = 0
  while (i < args.length && (args[i] ?? '').startsWith('-')) {
    if (args[i] === '-C' && i + 1 < args.length) {
      gitDir = joinDir(gitDir, args[i + 1])
      i += 2
    } else if (args[i] === '-c' && i + 1 < args.length) i += 2
    else i += 1
  }
  const sub = args[i]
  const rest = args.slice(i + 1)
  if (sub === 'reset' && rest.includes('--hard')) return { kind: 'git', op: 'reset-hard', command: 'git reset --hard', dir: gitDir, args: rest }
  if (sub === 'clean' && !rest.some(a => a === '-n' || a === '--dry-run' || /^-[a-zA-Z]*n/.test(a))) {
    return { kind: 'git', op: 'clean', command: 'git clean', dir: gitDir, args: rest }
  }
  if (sub === 'push' && rest.some(a => a === '--force' || a === '-f' || a.startsWith('--force-with-lease') || /^\+/.test(a))) {
    return { kind: 'git', op: 'push-force', command: 'git push --force', dir: gitDir, args: rest }
  }
  const stagedOnly = sub === 'restore' && rest.includes('--staged') && !rest.includes('--worktree') && !rest.includes('-W')
  if ((sub === 'checkout' || sub === 'restore') && rest.includes('.') && !stagedOnly) {
    return { kind: 'git', op: 'discard', command: `git ${sub} -- .`, dir: gitDir, args: rest }
  }
  return null
}

function migration(name: string, args: string[], dir: string | null): MigrationRisk | null {
  const line = [name, ...args].join(' ')
  if (/\balembic\s+upgrade\b/.test(line)) return { kind: 'migrate', tool: 'alembic', command: 'alembic upgrade', dir }
  if (/\bdb:migrate(?!:status\b)/.test(line)) return { kind: 'migrate', tool: 'rails', command: 'db:migrate', dir }
  if (/\bprisma\s+migrate\s+(dev|deploy|reset)\b/.test(line)) return { kind: 'migrate', tool: 'prisma', command: 'prisma migrate', dir }
  if (/\bmanage\.py\s+migrate\b/.test(line)) return { kind: 'migrate', tool: 'django', command: 'manage.py migrate', dir }
  if (!READ_ONLY.has(name.toLowerCase()) && args.includes('migrate')) return { kind: 'migrate', tool: 'other', command: 'migrate', dir }
  return null
}

/** One segment: a risk, a change of folder or nothing. */
function classifySegment(
  words: string[],
  dir: string | null,
  stack: (string | null)[],
  shell: Shell,
  input: string[] | null,
  inVenv: boolean,
): Risk | DirChange | null {
  const [first, ...args] = stripPrefixes(words, shell)
  if (first === undefined) return null
  const name = commandName(first, shell)
  const target = () => {
    if (shell === 'bash') return args[0]
    for (let i = 0; i < args.length; i++) {
      const a = args[i] ?? ''
      if (!a.startsWith('-')) return a
      if (isParam(a, 'path', 1) || isParam(a, 'literalpath', 1)) return a.includes(':') ? a.slice(a.indexOf(':') + 1) : args[i + 1]
    }
    return undefined
  }
  if (name === 'cd' || (shell === 'powershell' && POWERSHELL_CD.has(name))) {
    const a = target()
    return { cd: a === '-' ? '-' : joinDir(dir, a) }
  }
  if (PUSHD.has(name)) {
    stack.push(dir)
    return { cd: joinDir(dir, target()) }
  }
  if (POPD.has(name)) return { cd: stack.length > 0 ? (stack.pop() ?? null) : '-' }
  if (shell === 'bash' && name === 'rm') {
    const r = bashDelete(args, dir)
    if (r) return r
  }
  if (shell === 'powershell' && POWERSHELL_DELETE.has(name)) {
    const r = powershellDelete(name === 'remove-item' ? 'Remove-Item' : name, args, dir)
    if (r) return r
  }
  if (name === 'git') {
    const r = gitRisk(args, dir)
    if (r) return r
  }
  return installRisk(first, name, args, dir, shell, input, inVenv) ?? migration(name, args, dir)
}

/** Every risky segment of a command line, in order; empty when there is none. */
export function classify(command: string, shell: Shell): Risk[] {
  const risks: Risk[] = []
  let dir: string | null = null
  const subshells: (string | null)[] = []
  const stack: (string | null)[] = []
  let previous: string[] | null = null
  let inVenv = false
  for (const segment of segments(command, shell)) {
    for (let k = 0; k < segment.opens; k++) subshells.push(dir)
    const input = segment.piped ? previous : null
    const r: Risk | DirChange | null = segment.words.length > 0 ? classifySegment(segment.words, dir, stack, shell, input, inVenv) : null
    if (r !== null && 'kind' in r) risks.push(r)
    else if (r !== null) dir = r.cd
    if (segment.words.length > 0) {
      if (activatesVenv(segment.words, shell)) inVenv = true
      previous = stripPrefixes(segment.words, shell)
    }
    for (let k = 0; k < segment.closes && subshells.length > 0; k++) dir = subshells.pop() ?? null
  }
  return risks
}

files.hooks/measure.ts:
// What a risky command would change, measured without running it. Returns facts, never prose:
// the words live in messages.ts. It never sees `$`: register.tsx hands it a Probe of literal
// engine calls, so it is tested with a plain object.

import type { GitRisk, MigrationRisk, Risk } from './classify'
import { type InstallRisk, npmPackageName } from './installs'
import { baseName, dirOf, hasWildcards, positionals, relativeTo, resolvePath, wildcardToRegex } from './shell'

export type Stat = { kind: string; size: number; isLink: boolean }
export type Entry = Stat & { name: string }
export type Run = { exitCode: number; stdout: string; stderr: string }

/** What measuring needs from the engine. `stat` and `list` give null on a missing path; `run` never throws. */
export type Probe = {
  windows: boolean
  home: string
  now(): Promise<number>
  stat(path: string): Promise<Stat | null>
  list(path: string): Promise<Entry[] | null>
  run(argv: string[], options: { cwd?: string; timeoutMs: number; env?: Record<string, string> }): Promise<Run>
}

export type Facts =
  | { kind: 'unmeasured'; reason: 'missing-dir' | 'error'; detail: string }
  | { kind: 'delete'; targets: string[]; found: number; files: number; bytes: number; sample: string[]; truncated: boolean; links: number }
  | { kind: 'clean'; ok: boolean; paths: string[]; error: string }
  | { kind: 'discard'; ok: boolean; files: string[]; commits: string[]; shortstat: string; error: string }
  | { kind: 'push'; target: string; source: string; known: boolean; commits: string[] }
  | { kind: 'migrate'; argv: string[] | null; ok: boolean; pending: string[] }
  | { kind: 'install'; installed: Record<string, string> | null }

/** How many paths a list keeps; the rest is only counted. */
export const LIST_MAX = 10
const WALK_MAX = 20_000
const WALK_MS = 8_000
/** git in English whatever the person's locale: its output is parsed. */
const GIT_ENV = { LC_ALL: 'C', LANGUAGE: 'C' }

/** Never throws: what could not be measured comes back as `unmeasured`. */
export async function measure(risk: Risk, cwd: string, probe: Probe): Promise<Facts> {
  try {
    if (risk.kind === 'install') return await measureInstall(risk, probe)
    if (risk.kind === 'delete') return await measureDelete(risk.targets, cwd, probe)
    if (risk.kind === 'migrate') return await measureMigration(risk, cwd, probe)
    if (risk.op === 'push-force') return await measurePush(risk, cwd, probe)
    if (risk.op === 'clean') return await measureClean(risk, cwd, probe)
    return await measureDiscard(risk, cwd, probe)
  } catch (error) {
    return { kind: 'unmeasured', reason: 'error', detail: String(error instanceof Error ? error.message : error).slice(0, 200) }
  }
}

// ---------------------------------------------------------------------------
// Deletes

/** The paths a target names; with wildcards, only in its last part. */
async function expand(target: string, cwd: string, probe: Probe): Promise<string[]> {
  const path = resolvePath(cwd, target, probe.home)
  if (!hasWildcards(path)) return (await probe.stat(path)) ? [path] : []
  const parent = dirOf(path)
  if (hasWildcards(parent)) return []
  const pattern = wildcardToRegex(baseName(path))
  const entries = (await probe.list(parent)) ?? []
  return entries.filter(e => pattern.test(e.name)).map(e => `${parent.replace(/\/$/, '')}/${e.name}`)
}

async function measureDelete(targets: string[], cwd: string, probe: Probe): Promise<Facts> {
  const deadline = (await probe.now()) + WALK_MS
  const sample: string[] = []
  let files = 0
  let bytes = 0
  let found = 0
  let truncated = false
  // Symbolic links and junctions, counted but never followed: Windows PowerShell's Remove-Item -Recurse can delete through one.
  let links = 0
  const count = (path: string, size: number) => {
    files++
    bytes += size
    if (sample.length < LIST_MAX) sample.push(relativeTo(cwd, path))
    if (files >= WALK_MAX) truncated = true
  }
  for (const target of targets) {
    for (const path of await expand(target, cwd, probe)) {
      if (truncated) break
      found++
      const st = await probe.stat(path)
      if (st === null) continue
      if (st.isLink) links++
      if (st.kind !== 'dir' || st.isLink) {
        count(path, st.size)
        continue
      }
      let level = [path]
      while (level.length > 0 && !truncated) {
        const below: string[] = []
        for (const dir of level) {
          for (const e of (await probe.list(dir)) ?? []) {
            const child = `${dir.replace(/\/$/, '')}/${e.name}`
            if (e.isLink) links++
            if (e.kind === 'dir' && !e.isLink) below.push(child)
            else count(child, e.size)
            if (truncated) break
          }
          if (truncated || (await probe.now()) > deadline) {
            truncated = true
            break
          }
        }
        level = below
      }
    }
  }
  return { kind: 'delete', targets, found, files, bytes, sample, truncated, links }
}

// ---------------------------------------------------------------------------
// git

const git = (probe: Probe, cwd: string, args: string[]) => probe.run(['git', ...args], { cwd, timeoutMs: 15_000, env: GIT_ENV })

/** `git clean` arguments for a dry run: `-n` is added, and `-f`, `-i` and `-q` would change it. */
export function cleanDryRunArgs(args: string[]): string[] {
  const options: string[] = []
  const paths: string[] = []
  for (let i = 0; i < args.length; i++) {
    const a = args[i] ?? ''
    if (a === '--') {
      paths.push(...args.slice(i + 1))
      break
    }
    if (a === '-e' || a === '--exclude') {
      options.push(a, args[i + 1] ?? '')
      i++
    } else if (a.startsWith('--exclude=') || /^-e./.test(a)) options.push(a)
    else if (/^-[a-zA-Z]+$/.test(a)) {
      const kept = a.replace(/[finq]/g, '')
      if (kept !== '-') options.push(kept)
    } else if (!a.startsWith('-')) paths.push(a)
  }
  return ['clean', '-n', ...options, '--', ...paths]
}

async function measureClean(risk: GitRisk, cwd: string, probe: Probe): Promise<Facts> {
  const run = await git(probe, cwd, cleanDryRunArgs(risk.args))
  if (run.exitCode !== 0) return { kind: 'clean', ok: false, paths: [], error: run.stderr.trim().slice(0, 200) }
  const paths = run.stdout
    .split('\n')
    .filter(l => l.startsWith('Would remove '))
    .map(l => l.slice('Would remove '.length))
  return { kind: 'clean', ok: true, paths, error: '' }
}

/** The commit `git reset --hard` moves to (HEAD when it names none). */
export function resetTarget(args: string[]): string {
  const end = args.indexOf('--')
  return (end < 0 ? args : args.slice(0, end)).find(a => !a.startsWith('-')) ?? 'HEAD'
}

async function measureDiscard(risk: GitRisk, cwd: string, probe: Probe): Promise<Facts> {
  const status = await git(probe, cwd, ['status', '--porcelain'])
  if (status.exitCode !== 0) return { kind: 'discard', ok: false, files: [], commits: [], shortstat: '', error: status.stderr.trim().slice(0, 200) }
  const rows = status.stdout.split('\n').filter(l => l.length > 3 && !l.startsWith('??'))
  const reset = risk.op === 'reset-hard'
  // reset --hard loses staged and unstaged changes; checkout -- . only unstaged ones.
  const files = (reset ? rows : rows.filter(l => l[1] !== ' ')).map(l => `${l.slice(0, 2)} ${l.slice(3)}`)
  const target = reset ? resetTarget(risk.args) : 'HEAD'
  const commits = target === 'HEAD' ? [] : (await git(probe, cwd, ['log', '--oneline', '--no-decorate', `${target}..HEAD`])).stdout.split('\n').filter(Boolean)
  const shortstat = (await git(probe, cwd, ['diff', '--shortstat', reset ? target : '--'])).stdout.trim()
  return { kind: 'discard', ok: true, files, commits, shortstat, error: '' }
}

const PUSH_VALUE = new Set(['-o', '--push-option', '--repo', '--receive-pack', '--exec'])

async function measurePush(risk: GitRisk, cwd: string, probe: Probe): Promise<Facts> {
  const [remote, refspec] = positionals(risk.args, PUSH_VALUE)
  let source = 'HEAD'
  let target = ''
  if (refspec) {
    const ref = refspec.replace(/^\+/, '')
    const [from, to] = ref.includes(':') ? ref.split(':') : [ref, ref]
    source = from || 'HEAD'
    target = `${remote ?? 'origin'}/${(to ?? '').replace(/^refs\/heads\//, '')}`
  } else if (remote === undefined) {
    // No remote and no branch: wherever this branch pushes to.
    const push = await git(probe, cwd, ['rev-parse', '--abbrev-ref', '--symbolic-full-name', '@{push}'])
    if (push.exitCode === 0 && push.stdout.trim()) target = push.stdout.trim()
  }
  if (!target || target.endsWith('/') || target.endsWith('/HEAD')) {
    const branch = (await git(probe, cwd, ['rev-parse', '--abbrev-ref', 'HEAD'])).stdout.trim()
    target = `${remote ?? 'origin'}/${branch}`
  }
  if ((await git(probe, cwd, ['rev-parse', '--verify', '--quiet', target])).exitCode !== 0) return { kind: 'push', target, source, known: false, commits: [] }
  const commits = (await git(probe, cwd, ['log', '--oneline', '--no-decorate', `${source}..${target}`])).stdout.split('\n').filter(Boolean)
  return { kind: 'push', target, source, known: true, commits }
}

// ---------------------------------------------------------------------------
// Migrations

const LISTERS: Record<string, { argv: (windows: boolean) => string[]; pending: (l: string) => boolean; clean: (l: string) => string }> = {
  django: { argv: w => [w ? 'python' : 'python3', 'manage.py', 'showmigrations', '--plan'], pending: l => l.startsWith('[ ]'), clean: l => l.slice(4) },
  alembic: { argv: () => ['alembic', 'history', '-r', 'current:head'], pending: l => l.includes('->'), clean: l => l },
  rails: { argv: () => ['bin/rails', 'db:migrate:status'], pending: l => /^\s*down\b/.test(l), clean: l => l.trim() },
  prisma: { argv: w => [w ? 'npx.cmd' : 'npx', '--no-install', 'prisma', 'migrate', 'status'], pending: l => /^\s{2}\S/.test(l), clean: l => l.trim() },
}

async function measureMigration(risk: MigrationRisk, cwd: string, probe: Probe): Promise<Facts> {
  const lister = LISTERS[risk.tool]
  if (lister === undefined) return { kind: 'migrate', argv: null, ok: false, pending: [] }
  const argv = lister.argv(probe.windows)
  const run = await probe.run(argv, { cwd, timeoutMs: 20_000 })
  if (run.exitCode !== 0) return { kind: 'migrate', argv, ok: false, pending: [] }
  return { kind: 'migrate', argv, ok: true, pending: run.stdout.split('\n').filter(lister.pending).map(lister.clean) }
}

// ---------------------------------------------------------------------------
// Installs

/** The global npm packages and their versions, read from disk only (no network); null if unreadable. */
async function globalNpm(probe: Probe): Promise<Record<string, string> | null> {
  const run = await probe.run([probe.windows ? 'npm.cmd' : 'npm', 'ls', '-g', '--depth=0', '--json'], { timeoutMs: 15_000 })
  try {
    const data = JSON.parse(run.stdout) as { dependencies?: Record<string, { version?: unknown }> }
    return Object.fromEntries(Object.entries(data.dependencies ?? {}).map(([name, d]) => [name, typeof d.version === 'string' ? d.version : '?']))
  } catch {
    return null
  }
}

async function measureInstall(risk: InstallRisk, probe: Probe): Promise<Facts> {
  return { kind: 'install', installed: risk.manager === 'npm' && risk.packages.length > 0 ? await globalNpm(probe) : null }
}

/** The installed version of an npm package spec (`typescript@5.7` → `5.6.2`), if any. */
export function installedVersion(installed: Record<string, string> | null, spec: string): string | undefined {
  return installed?.[npmPackageName(spec)]
}

